div.script:
$('#search-query-sm').keyup(function(){
	var query = $(this).val();
	if(query.length > 2){
		$.ajax({
			type: "get",
			url: "https://www.actual-adventure.com/search-content",
			data: {query:query},
			success:function(res){
				$('#search-result-sm').html(res);
				$('#search-result-sm').show();
			}
		})
	}else{
		$('#search-result-sm').html('');
		$('#search-result-sm').hide();
	}
})

body.script:
$("#destination-select").change(function() {
	var destination = $(this).val();
	$.ajax({
		type:"get",
		url:"https://www.actual-adventure.com/get-activities",
		data:{destination:destination},
		success:function(res){
			$('#activity-select').html(res);
		}
	})
})
$("#activity-select").change(function() {
	var activity = $(this).val();
	var destination = $('#destination-select').val();
	$.ajax({
		type:"get",
		url:"https://www.actual-adventure.com/get-duration",
		data:{activity:activity,destination:destination},
		success:function(res){
			$('#duration-select').html(res);
		}
	})
})


$(document).ready(function() {
	var duration = 500;
	$(window).scroll(function() {
		if ($(this).scrollTop() > 200) {
			$('.to-top').fadeIn(duration);
		} else {
			$('.to-top').fadeOut(duration);
		}
	});
	$('.to-top').click(function(event) {
		event.preventDefault();
		$('html').animate({scrollTop: 0}, duration);
		return false;
	})
	$('.footer-logo').click(function() {
		window.location.href = "/";
	})
});
